36	/** Keyed by schema-file id, templates by name, since two schema ids can share one local id. An absent entry keeps the local value. */
37	export type SchemaMergePlan = {
38	  nodeTypeFields: ReadonlyMap<string, ReadonlySet<string>>;
39	  relationTypeFields: ReadonlyMap<string, ReadonlySet<string>>;
40	  templateNames: ReadonlySet<string>;
41	};
