43	export type LoadedSchemaFile = {
44	  sourcePath: string;
45	  schemaFile: DiscourseSchemaFile;
46	  matchPlan: SchemaImportMatchPlan;
47	};
48	
49	export type ImportPreviewStats = {
50	  nodeTypes: { total: number; new: number; existing: number };
51	  relationTypes: { total: number; new: number; existing: number };
52	  discourseRelations: { total: number; new: number; existing: number };
53	  templates: { total: number; new: number; existing: number };
54	};
