62	/** Relation triples are absent from `merged` because endpoints are their identity. */
63	export type SpecImportApplyResult = {
64	  created: {
65	    nodeTypes: number;
66	    relationTypes: number;
67	    discourseRelations: number;
68	    templates: number;
69	  };
70	  merged: {
71	    nodeTypes: number;
72	    relationTypes: number;
73	    templates: number;
74	  };
75	};
