77	const buildSchemaImportMatchPlan = ({
78	  schemaFile,
79	  localNodeTypes,
80	  localRelationTypes,
81	  localDiscourseRelations,
82	  localTemplateNames,
83	}: {
84	  schemaFile: DiscourseSchemaFile;
85	  localNodeTypes: DiscourseNode[];
86	  localRelationTypes: DiscourseRelationType[];
87	  localDiscourseRelations: DiscourseRelation[];
88	  localTemplateNames: Set<string>;
89	}): SchemaImportMatchPlan => {
90	  const nodeTypeIdMapping = new Map<string, string>();
91	  const existingNodeTypeIds = new Set<string>();
92	  const collapsedNodeTypeIds = new Set<string>();
93	  const localNodeTypeIds = new Set(
94	    localNodeTypes.map((nodeType) => nodeType.id),
95	  );
96	  // Grows as types are planned, so "Event" and "event" in one file collapse instead of creating two.
97	  const knownNodeTypes = [...localNodeTypes];
98	
99	  for (const nodeType of schemaFile.nodeTypes) {
100	    const localMatch = findLocalNodeTypeMatch({
101	      localNodeTypes: knownNodeTypes,
102	      id: nodeType.id,
103	      name: nodeType.name,
104	    });
105	    if (localMatch) {
106	      nodeTypeIdMapping.set(nodeType.id, localMatch.id);
107	      existingNodeTypeIds.add(nodeType.id);
108	      // Matched a type planned earlier in this file, not one the vault holds.
109	      if (!localNodeTypeIds.has(localMatch.id)) {
110	        collapsedNodeTypeIds.add(nodeType.id);
111	      }
112	      continue;
113	    }
114	
115	    nodeTypeIdMapping.set(nodeType.id, nodeType.id);
116	    knownNodeTypes.push(nodeType);
117	  }
118	
119	  const relationTypeIdMapping = new Map<string, string>();
120	  const existingRelationTypeIds = new Set<string>();
121	  const collapsedRelationTypeIds = new Set<string>();
122	  const localRelationTypeIds = new Set(
123	    localRelationTypes.map((relationType) => relationType.id),
124	  );
125	  const knownRelationTypes = [...localRelationTypes];
126	
127	  for (const relationType of schemaFile.relationTypes) {
128	    const localMatch = findLocalRelationTypeMatch({
129	      localRelationTypes: knownRelationTypes,
130	      id: relationType.id,
131	      label: relationType.label,
132	    });
133	    if (localMatch) {
134	      relationTypeIdMapping.set(relationType.id, localMatch.id);
135	      existingRelationTypeIds.add(relationType.id);
136	      if (!localRelationTypeIds.has(localMatch.id)) {
137	        collapsedRelationTypeIds.add(relationType.id);
138	      }
139	      continue;
140	    }
141	
142	    relationTypeIdMapping.set(relationType.id, relationType.id);
143	    knownRelationTypes.push(relationType);
144	  }
145	
146	  const existingDiscourseRelationIds = new Set<string>();
147	  for (const relation of schemaFile.discourseRelations) {
148	    const existing = findExistingTriple({
149	      discourseRelations: localDiscourseRelations,
150	      sourceId: nodeTypeIdMapping.get(relation.sourceId) ?? relation.sourceId,
151	      destinationId:
152	        nodeTypeIdMapping.get(relation.destinationId) ?? relation.destinationId,
153	      relationshipTypeId:
154	        relationTypeIdMapping.get(relation.relationshipTypeId) ??
155	        relation.relationshipTypeId,
156	    });
157	    if (existing) {
158	      existingDiscourseRelationIds.add(relation.id);
159	    }
160	  }
161	
162	  const existingTemplateNames = new Set<string>();
163	  for (const template of schemaFile.templates) {
164	    if (localTemplateNames.has(template.name)) {
165	      existingTemplateNames.add(template.name);
166	    }
167	  }
168	
169	  return {
170	    nodeTypeIdMapping,
171	    relationTypeIdMapping,
172	    existingNodeTypeIds,
173	    existingRelationTypeIds,
174	    collapsedNodeTypeIds,
175	    collapsedRelationTypeIds,
176	    existingDiscourseRelationIds,
177	    existingTemplateNames,
178	    localTemplateNames,
179	  };
180	};
