182	const buildPreviewStats = ({
183	  schemaFile,
184	  matchPlan,
185	}: {
186	  schemaFile: DiscourseSchemaFile;
187	  matchPlan: SchemaImportMatchPlan;
188	}): ImportPreviewStats => {
189	  return {
190	    // A collapsed id is neither created nor held by the vault, so counting it as existing would name a type the user does not have.
191	    nodeTypes: {
192	      total: schemaFile.nodeTypes.length - matchPlan.collapsedNodeTypeIds.size,
193	      existing:
194	        matchPlan.existingNodeTypeIds.size -
195	        matchPlan.collapsedNodeTypeIds.size,
196	      new: schemaFile.nodeTypes.length - matchPlan.existingNodeTypeIds.size,
197	    },
198	    relationTypes: {
199	      total:
200	        schemaFile.relationTypes.length -
201	        matchPlan.collapsedRelationTypeIds.size,
202	      existing:
203	        matchPlan.existingRelationTypeIds.size -
204	        matchPlan.collapsedRelationTypeIds.size,
205	      new:
206	        schemaFile.relationTypes.length -
207	        matchPlan.existingRelationTypeIds.size,
208	    },
209	    discourseRelations: {
210	      total: schemaFile.discourseRelations.length,
211	      existing: matchPlan.existingDiscourseRelationIds.size,
212	      new:
213	        schemaFile.discourseRelations.length -
214	        matchPlan.existingDiscourseRelationIds.size,
215	    },
216	    templates: {
217	      total: schemaFile.templates.length,
218	      existing: matchPlan.existingTemplateNames.size,
219	      new: schemaFile.templates.length - matchPlan.existingTemplateNames.size,
220	    },
221	  };
222	};
