224	const readOverlappingTemplateContents = async ({
225	  plugin,
226	  matchPlan,
227	}: {
228	  plugin: DiscourseGraphPlugin;
229	  matchPlan: SchemaImportMatchPlan;
230	}): Promise<Map<string, string>> => {
231	  const entries = await Promise.all(
232	    [...matchPlan.existingTemplateNames].map(async (templateName) => {
233	      const content = await readTemplateContent({
234	        app: plugin.app,
235	        templateName,
236	      });
237	      return content === null ? [] : [[templateName, content] as const];
238	    }),
239	  );
240	  return new Map(entries.flat());
241	};
