243	export const pickAndPreviewSchemaImport = async ({
244	  plugin,
245	}: {
246	  plugin: DiscourseGraphPlugin;
247	}): Promise<SpecImportPreview> => {
248	  const file = await openJsonFromUserLocation({
249	    title: "Import discourse graph schema",
250	  });
251	  const schemaFile = parseDgSchemaFile(JSON.parse(file.content) as unknown);
252	  const localTemplateNames = new Set(getTemplateFiles(plugin.app));
253	  const matchPlan = buildSchemaImportMatchPlan({
254	    schemaFile,
255	    localNodeTypes: plugin.settings.nodeTypes,
256	    localRelationTypes: plugin.settings.relationTypes,
257	    localDiscourseRelations: plugin.settings.discourseRelations,
258	    localTemplateNames,
259	  });
260	
261	  const loadedSchemaFile: LoadedSchemaFile = {
262	    sourcePath: file.sourcePath,
263	    schemaFile,
264	    matchPlan,
265	  };
266	
267	  const localTemplateContents = await readOverlappingTemplateContents({
268	    plugin,
269	    matchPlan,
270	  });
271	
272	  return {
273	    loadedSchemaFile,
274	    previewStats: buildPreviewStats({ schemaFile, matchPlan }),
275	    conflicts: buildSchemaConflicts({
276	      schemaFile,
277	      matchPlan,
278	      localNodeTypes: plugin.settings.nodeTypes,
279	      localRelationTypes: plugin.settings.relationTypes,
280	      localTemplateContents,
281	    }),
282	  };
283	};
