285	/** Keyed off what actually landed, so a failed creation leaves no dangling reference; an imported copy wins over a same-named local one. */
286	const resolveTemplateReference = ({
287	  template,
288	  importedTemplateNames,
289	  localTemplateNames,
290	}: {
291	  template: string | undefined;
292	  importedTemplateNames: ReadonlyMap<string, string>;
293	  localTemplateNames: ReadonlySet<string>;
294	}): string | undefined => {
295	  if (!template) return undefined;
296	  const importedName = importedTemplateNames.get(template);
297	  if (importedName) return importedName;
298	  return localTemplateNames.has(template) ? template : undefined;
299	};
300	
301	const mergeNodeTypeFields = ({
302	  local,
303	  imported,
304	  fields,
305	  importedTemplateNames,
306	  localTemplateNames,
307	}: {
308	  local: DiscourseNode;
309	  imported: DiscourseNode;
310	  fields: ReadonlySet<string>;
311	  importedTemplateNames: ReadonlyMap<string, string>;
312	  localTemplateNames: ReadonlySet<string>;
313	}): DiscourseNode => {
314	  const merged: DiscourseNode = { ...local, modified: Date.now() };
315	  for (const field of MERGEABLE_NODE_TYPE_FIELDS) {
316	    if (!fields.has(field)) continue;
317	    // TS cannot correlate merged[field] with imported[field] across a key union; the `satisfies` clause makes the write sound.
318	    (merged as Record<string, unknown>)[field] = imported[field];
319	  }
320	  // Same guard the create path applies, so a merged reference cannot dangle.
321	  if (fields.has("template")) {
322	    merged.template = resolveTemplateReference({
323	      template: merged.template,
324	      importedTemplateNames,
325	      localTemplateNames,
326	    });
327	  } else if (merged.template) {
328	    // Both sides naming the same template yields no `template` change row, so the reference must still follow a chosen imported body into its renamed copy.
329	    merged.template =
330	      importedTemplateNames.get(merged.template) ?? merged.template;
331	  }
332	  return merged;
333	};
334	
335	const mergeRelationTypeFields = ({
336	  local,
337	  imported,
338	  fields,
339	}: {
340	  local: DiscourseRelationType;
341	  imported: DiscourseRelationType;
342	  fields: ReadonlySet<string>;
343	}): DiscourseRelationType => {
344	  const merged: DiscourseRelationType = { ...local, modified: Date.now() };
345	  for (const field of MERGEABLE_RELATION_TYPE_FIELDS) {
346	    if (!fields.has(field)) continue;
347	    (merged as Record<string, unknown>)[field] = imported[field];
348	  }
349	  if (fields.has("color")) {
350	    merged.color = toTldrawColor(merged.color);
351	  }
352	  return merged;
353	};
