355	export const applySchemaImportSelection = async ({
356	  plugin,
357	  loadedSchemaFile,
358	  selection,
359	  mergePlan,
360	  onWarning = () => {},
361	}: {
362	  plugin: DiscourseGraphPlugin;
363	  loadedSchemaFile: LoadedSchemaFile;
364	  selection: SchemaSelection;
365	  mergePlan?: SchemaMergePlan;
366	  onWarning?: (message: string) => void;
367	}): Promise<SpecImportApplyResult> => {
368	  const { schemaFile, matchPlan } = loadedSchemaFile;
369	  const sourceSpaceUri = canonicalObsidianUrl(schemaFile.vaultId);
370	  const selectedTemplateNames = new Set(selection.templateNames);
371	  const selectedNodeTypeIds = new Set(selection.nodeTypeIds);
372	  const selectedRelationTypeIds = new Set(selection.relationTypeIds);
373	  const selectedRelationIds = new Set(selection.discourseRelationIds);
374	
375	  let templatesCreated = 0;
376	  let templatesMerged = 0;
377	  /** Schema-file template name to the name it actually landed under; these differ when the copy sits beside a local template. */
378	  const importedTemplateNames = new Map<string, string>();
379	  const templatesByName = new Map(
380	    schemaFile.templates.map((template) => [template.name, template]),
381	  );
382	  for (const templateName of selectedTemplateNames) {
383	    const template = templatesByName.get(templateName);
384	    if (!template) {
385	      onWarning(
386	        `Template "${templateName}" was selected but not found in schema file.`,
387	      );
388	      continue;
389	    }
390	
391	    if (matchPlan.existingTemplateNames.has(templateName)) {
392	      if (!mergePlan?.templateNames.has(templateName)) {
393	        continue;
394	      }
395	
396	      // Never clobber the local template: the copy lands beside it and the node type is repointed at the copy.
397	      const copyResult = await createTemplateFileWithUniqueName({
398	        app: plugin.app,
399	        templateName: template.name,
400	        sourceName: schemaFile.vaultName,
401	        content: template.content,
402	      });
403	      if (copyResult.created) {
404	        importedTemplateNames.set(template.name, copyResult.templateName);
405	        templatesMerged += 1;
406	      } else {
407	        onWarning(
408	          `Template "${template.name}" not imported: ${copyResult.reason}.`,
409	        );
410	      }
411	      continue;
412	    }
413	
414	    const result = await createTemplateFile({
415	      app: plugin.app,
416	      templateName: template.name,
417	      content: template.content,
418	    });
419	
420	    if (result.created) {
421	      // The landed basename, not the requested name: creation sanitizes, and a node type referencing the unsanitized name would resolve to no file.
422	      importedTemplateNames.set(template.name, result.templateName);
423	      templatesCreated += 1;
424	      continue;
425	    }
426	
427	    if (result.reason !== "template already exists") {
428	      onWarning(`Template "${template.name}" skipped: ${result.reason}.`);
429	    }
430	  }
431	
432	  const schemaNodeTypesById = new Map(
433	    schemaFile.nodeTypes.map((nodeType) => [nodeType.id, nodeType]),
434	  );
435	  const schemaRelationTypesById = new Map(
436	    schemaFile.relationTypes.map((relationType) => [
437	      relationType.id,
438	      relationType,
439	    ]),
440	  );
441	
442	  /** Where each schema id actually ended up, which diverges from the plan when settings moved since the preview. */
443	  const effectiveNodeTypeIds = new Map<string, string>();
444	  let nodeTypesCreated = 0;
445	  let nodeTypesMerged = 0;
446	  for (const nodeTypeId of selectedNodeTypeIds) {
447	    const importedNodeType = schemaNodeTypesById.get(nodeTypeId);
448	    if (!importedNodeType) {
449	      onWarning(
450	        `Node type "${nodeTypeId}" was selected but missing from schema file.`,
451	      );
452	      continue;
453	    }
454	
455	    // Re-matched against live settings rather than the plan: the plan is a preview-time snapshot, and an entry that collapsed onto another file entry has nothing to merge into unless that entry was also selected.
456	    const localMatch = findLocalNodeTypeMatch({
457	      localNodeTypes: plugin.settings.nodeTypes,
458	      id: matchPlan.nodeTypeIdMapping.get(nodeTypeId) ?? nodeTypeId,
459	      name: importedNodeType.name,
460	    });
461	
462	    if (localMatch) {
463	      effectiveNodeTypeIds.set(nodeTypeId, localMatch.id);
464	      const mergedFields = mergePlan?.nodeTypeFields.get(nodeTypeId);
465	      if (!mergedFields?.size) {
466	        continue;
467	      }
468	
469	      const localIndex = plugin.settings.nodeTypes.indexOf(localMatch);
470	      const nextNodeTypes = [...plugin.settings.nodeTypes];
471	      const mergedNodeType = mergeNodeTypeFields({
472	        local: nextNodeTypes[localIndex]!,
473	        imported: importedNodeType,
474	        fields: mergedFields,
475	        importedTemplateNames,
476	        localTemplateNames: matchPlan.localTemplateNames,
477	      });
478	      if (
479	        mergedFields.has("template") &&
480	        importedNodeType.template &&
481	        !mergedNodeType.template
482	      ) {
483	        onWarning(
484	          `Template "${importedNodeType.template}" was not imported and is not in this vault, so "${mergedNodeType.name}" was merged without a template reference.`,
485	        );
486	      }
487	      nextNodeTypes[localIndex] = mergedNodeType;
488	      plugin.settings.nodeTypes = nextNodeTypes;
489	      nodeTypesMerged += 1;
490	      continue;
491	    }
492	
493	    effectiveNodeTypeIds.set(nodeTypeId, importedNodeType.id);
494	    const newNodeType: DiscourseNode = {
495	      ...importedNodeType,
496	      template: resolveTemplateReference({
497	        template: importedNodeType.template,
498	        importedTemplateNames,
499	        localTemplateNames: matchPlan.localTemplateNames,
500	      }),
501	      importedFromRid: buildSchemaRid({
502	        spaceUri: sourceSpaceUri,
503	        localId: importedNodeType.id,
504	      }),
505	      modified: Date.now(),
506	    };
507	    plugin.settings.nodeTypes = [...plugin.settings.nodeTypes, newNodeType];
508	    nodeTypesCreated += 1;
509	  }
510	
511	  const effectiveRelationTypeIds = new Map<string, string>();
512	  let relationTypesCreated = 0;
513	  let relationTypesMerged = 0;
514	  for (const relationTypeId of selectedRelationTypeIds) {
515	    const importedRelationType = schemaRelationTypesById.get(relationTypeId);
516	    if (!importedRelationType) {
517	      onWarning(
518	        `Relation type "${relationTypeId}" was selected but missing from schema file.`,
519	      );
520	      continue;
521	    }
522	
523	    const localMatch = findLocalRelationTypeMatch({
524	      localRelationTypes: plugin.settings.relationTypes,
525	      id: matchPlan.relationTypeIdMapping.get(relationTypeId) ?? relationTypeId,
526	      label: importedRelationType.label,
527	    });
528	
529	    if (localMatch) {
530	      effectiveRelationTypeIds.set(relationTypeId, localMatch.id);
531	      const mergedFields = mergePlan?.relationTypeFields.get(relationTypeId);
532	      if (!mergedFields?.size) {
533	        continue;
534	      }
535	
536	      const localIndex = plugin.settings.relationTypes.indexOf(localMatch);
537	      const nextRelationTypes = [...plugin.settings.relationTypes];
538	      nextRelationTypes[localIndex] = mergeRelationTypeFields({
539	        local: nextRelationTypes[localIndex]!,
540	        imported: importedRelationType,
541	        fields: mergedFields,
542	      });
543	      plugin.settings.relationTypes = nextRelationTypes;
544	      relationTypesMerged += 1;
545	      continue;
546	    }
547	
548	    effectiveRelationTypeIds.set(relationTypeId, importedRelationType.id);
549	    const newRelationType: DiscourseRelationType = {
550	      ...importedRelationType,
551	      color: toTldrawColor(importedRelationType.color),
552	      importedFromRid: buildSchemaRid({
553	        spaceUri: sourceSpaceUri,
554	        localId: importedRelationType.id,
555	      }),
556	      // Accepted, not provisional: the user chose this file and hand-picked these items, so nothing is left to review.
557	      status: "accepted",
558	      modified: Date.now(),
559	    };
560	    plugin.settings.relationTypes = [
561	      ...plugin.settings.relationTypes,
562	      newRelationType,
563	    ];
564	    relationTypesCreated += 1;
565	  }
566	
567	  const hasNodeType = (id: string): boolean =>
568	    plugin.settings.nodeTypes.some((nodeType) => nodeType.id === id);
569	  const hasRelationType = (id: string): boolean =>
570	    plugin.settings.relationTypes.some(
571	      (relationType) => relationType.id === id,
572	    );
573	
574	  let discourseRelationsCreated = 0;
575	  for (const relation of schemaFile.discourseRelations) {
576	    if (!selectedRelationIds.has(relation.id)) {
577	      continue;
578	    }
579	
580	    // Where the endpoint actually landed takes precedence over the plan, which can name a type this run never created.
581	    const mappedSourceId =
582	      effectiveNodeTypeIds.get(relation.sourceId) ??
583	      matchPlan.nodeTypeIdMapping.get(relation.sourceId) ??
584	      relation.sourceId;
585	    const mappedDestinationId =
586	      effectiveNodeTypeIds.get(relation.destinationId) ??
587	      matchPlan.nodeTypeIdMapping.get(relation.destinationId) ??
588	      relation.destinationId;
589	    const mappedRelationTypeId =
590	      effectiveRelationTypeIds.get(relation.relationshipTypeId) ??
591	      matchPlan.relationTypeIdMapping.get(relation.relationshipTypeId) ??
592	      relation.relationshipTypeId;
593	
594	    // Checked against live settings, not the plan: two file relations can map to one triple after collapsing.
595	    const alreadyPresent = findExistingTriple({
596	      discourseRelations: plugin.settings.discourseRelations,
597	      sourceId: mappedSourceId,
598	      destinationId: mappedDestinationId,
599	      relationshipTypeId: mappedRelationTypeId,
600	    });
601	    if (alreadyPresent) {
602	      continue;
603	    }
604	
605	    // The selection UI keeps a triple's endpoints selected, but this layer owns settings integrity, so a dangling triple is refused rather than written.
606	    if (
607	      !hasNodeType(mappedSourceId) ||
608	      !hasNodeType(mappedDestinationId) ||
609	      !hasRelationType(mappedRelationTypeId)
610	    ) {
611	      const sourceName =
612	        schemaNodeTypesById.get(relation.sourceId)?.name ?? relation.sourceId;
613	      const destinationName =
614	        schemaNodeTypesById.get(relation.destinationId)?.name ??
615	        relation.destinationId;
616	      const relationLabel =
617	        schemaRelationTypesById.get(relation.relationshipTypeId)?.label ??
618	        relation.relationshipTypeId;
619	      onWarning(
620	        `Relation "${sourceName} ${relationLabel} ${destinationName}" skipped: it references a type that is not in this vault.`,
621	      );
622	      continue;
623	    }
624	
625	    const newRelation: DiscourseRelation = {
626	      ...relation,
627	      id: uuidv7(),
628	      sourceId: mappedSourceId,
629	      destinationId: mappedDestinationId,
630	      relationshipTypeId: mappedRelationTypeId,
631	      importedFromRid: buildSchemaRid({
632	        spaceUri: sourceSpaceUri,
633	        localId: relation.id,
634	      }),
635	      status: "accepted",
636	      modified: Date.now(),
637	    };
638	    plugin.settings.discourseRelations = [
639	      ...plugin.settings.discourseRelations,
640	      newRelation,
641	    ];
642	    discourseRelationsCreated += 1;
643	  }
644	
645	  await plugin.saveSettings();
646	
647	  return {
648	    created: {
649	      nodeTypes: nodeTypesCreated,
650	      relationTypes: relationTypesCreated,
651	      discourseRelations: discourseRelationsCreated,
652	      templates: templatesCreated,
653	    },
654	    merged: {
655	      nodeTypes: nodeTypesMerged,
656	      relationTypes: relationTypesMerged,
657	      templates: templatesMerged,
658	    },
659	  };
660	};
