9	/** `existing*` hold schema-file ids that will not be created; resolve references through the id mappings, as a schema id may not survive the import. */
10	export type SchemaImportMatchPlan = {
11	  nodeTypeIdMapping: Map<string, string>;
12	  relationTypeIdMapping: Map<string, string>;
13	  existingNodeTypeIds: Set<string>;
14	  existingRelationTypeIds: Set<string>;
15	  /** Subset of `existing*` that matched another entry in the same file rather than the vault, so previews can exclude them from both counts. */
16	  collapsedNodeTypeIds: Set<string>;
17	  collapsedRelationTypeIds: Set<string>;
18	  existingDiscourseRelationIds: Set<string>;
19	  existingTemplateNames: Set<string>;
20	  localTemplateNames: Set<string>;
21	};
22	
23	export const normalizeSchemaLabel = (value: string): string => {
24	  return value.trim().toLowerCase();
25	};
26	
27	/** Match by id first: an id collision is stronger evidence than a name two vaults happen to share. */
28	export const findLocalNodeTypeMatch = ({
29	  localNodeTypes,
30	  id,
31	  name,
32	}: {
33	  localNodeTypes: DiscourseNode[];
34	  id: string;
35	  name: string;
36	}): DiscourseNode | undefined => {
37	  const matchById = localNodeTypes.find((nodeType) => nodeType.id === id);
38	  if (matchById) return matchById;
39	
40	  const normalizedName = normalizeSchemaLabel(name);
41	  return localNodeTypes.find(
42	    (nodeType) => normalizeSchemaLabel(nodeType.name) === normalizedName,
43	  );
44	};
45	
46	export const findLocalRelationTypeMatch = ({
47	  localRelationTypes,
48	  id,
49	  label,
50	}: {
51	  localRelationTypes: DiscourseRelationType[];
52	  id: string;
53	  label: string;
54	}): DiscourseRelationType | undefined => {
55	  const matchById = localRelationTypes.find(
56	    (relationType) => relationType.id === id,
57	  );
58	  if (matchById) return matchById;
59	
60	  const normalizedLabel = normalizeSchemaLabel(label);
61	  return localRelationTypes.find(
62	    (relationType) =>
63	      normalizeSchemaLabel(relationType.label) === normalizedLabel,
64	  );
65	};
66	
67	/** A triple is identified by its endpoints and relation type, not its id — ids are regenerated per vault. */
68	export const findExistingTriple = ({
69	  discourseRelations,
70	  sourceId,
71	  destinationId,
72	  relationshipTypeId,
73	}: {
74	  discourseRelations: DiscourseRelation[];
75	  sourceId: string;
76	  destinationId: string;
77	  relationshipTypeId: string;
78	}): DiscourseRelation | undefined => {
79	  return discourseRelations.find(
80	    (relation) =>
81	      relation.sourceId === sourceId &&
82	      relation.destinationId === destinationId &&
83	      relation.relationshipTypeId === relationshipTypeId,
84	  );
85	};
