87	/** Pins the "schema" RID subtype so both import paths produce identical RIDs. */
88	export const buildSchemaRid = ({
89	  spaceUri,
90	  localId,
91	}: {
92	  spaceUri: string;
93	  localId: string;
94	}): string => {
95	  return spaceUriAndLocalIdToRid(spaceUri, localId, "schema");
96	};
