56	const buildExistingItemNotes = ({
57	  existingSchemaIds,
58	  conflicts,
59	  category,
60	}: {
61	  existingSchemaIds: ReadonlySet<string>;
62	  conflicts: SchemaConflict[];
63	  category: SchemaConflict["category"];
64	}): Map<string, string> => {
65	  const changeCountBySchemaId = new Map(
66	    conflicts
67	      .filter((conflict) => conflict.category === category)
68	      .map((conflict) => [conflict.schemaId, conflict.changes.length]),
69	  );
70	  return new Map(
71	    [...existingSchemaIds].map((schemaId) => {
