134	      .map((conflict) => `${conflict.category}:${conflict.schemaId}`)
135	      .join(",")}`,
136	  });
137	
138	  const hasAnySelection =
139	    selection.selectedNodeTypeIds.size > 0 ||
140	    selection.selectedRelationTypeIds.size > 0 ||
141	    selection.selectedRelationIds.size > 0 ||
