273	        const fields = error.issues.map((i) => i.path.join(".")).join(", ");
274	        new Notice(
275	          `Schema file is incompatible with this version of the plugin. Invalid or missing fields: ${fields}`,
276	          8000,
277	        );
278	        return;
279	      }
280	      const message = error instanceof Error ? error.message : String(error);
281	      new Notice(`Failed to load schema file: ${message}`, 6000);
282	    } finally {
283	      setIsSelectingFile(false);
284	    }
285	  };
286	
287	  if (!preview) {
288	    return (
289	      <div>
290	        <h3 className="mb-2">Import discourse graph schema</h3>
291	        <p className="text-muted mb-4 text-sm">
292	          Pick a <code>dg-schema-*.json</code> file from your computer to
293	          preview and choose exactly what to import.
294	        </p>
295	
296	        <div className="mb-4 rounded border p-3 text-sm">
297	          Same dependency rules as export apply here during selection.
298	        </div>
299	
300	        <div className="flex justify-between">
301	          <button type="button" className="px-4 py-2" onClick={onClose}>
302	            Cancel
303	          </button>
304	          <button
305	            type="button"
306	            className="!bg-accent !text-on-accent rounded px-4 py-2"
307	            onClick={() => void handleSelectSchemaFile()}
308	            disabled={isSelectingFile}
309	          >
310	            {isSelectingFile ? "Opening..." : "Choose schema file"}
311	          </button>
312	        </div>
313	      </div>
314	    );
315	  }
316	
317	  return (
318	    <ImportPreviewSelection
319	      plugin={plugin}
320	      loadedSchemaFile={preview.loadedSchemaFile}
321	      previewStats={preview.previewStats}
322	      conflicts={preview.conflicts}
323	      isApplyingImport={isApplyingImport}
324	      setIsApplyingImport={setIsApplyingImport}
325	      onResetPreview={() => setPreview(null)}
326	      onClose={onClose}
327	    />
328	  );
329	};
