1	import type {
2	  DiscourseNode,
3	  DiscourseRelationType,
4	  DiscourseSchemaFile,
5	} from "~/types";
6	import type { SchemaImportMatchPlan } from "~/utils/schemaMatching";
7	import { toTldrawColor } from "~/utils/tldrawColors";
8	
9	/** Fields an import may overwrite. `name`/`label` are excluded: renaming a type does not retag its pages, so the vault would silently split. */
10	export const MERGEABLE_NODE_TYPE_FIELDS = [
11	  "format",
12	  "template",
13	  "description",
14	  "shortcut",
15	  "color",
16	  "tag",
17	  "keyImage",
18	  "folderPath",
19	] as const satisfies readonly (keyof DiscourseNode)[];
20	
21	export const MERGEABLE_RELATION_TYPE_FIELDS = [
22	  "complement",
23	  "color",
24	] as const satisfies readonly (keyof DiscourseRelationType)[];
25	
26	/** Templates are all-or-nothing: the whole file body is replaced or kept. */
27	export const TEMPLATE_CONTENT_FIELD = "content";
28	
29	export type SchemaFieldChange = {
30	  field: string;
31	  localValue: string | boolean | undefined;
32	  importedValue: string | boolean | undefined;
33	};
34	
35	export type SchemaConflictCategory = "nodeType" | "relationType" | "template";
36	
37	/** Keyed by schema-file id, not local id: the match plan can collapse two schema ids onto one local id. */
38	export type SchemaConflict = {
39	  category: SchemaConflictCategory;
40	  schemaId: string;
41	  label: string;
42	  changes: SchemaFieldChange[];
43	};
44	
45	/** A file with no value for a field is not asking to clear it; "" counts as absent, since settings persist a cleared field as "" but omit an unset one. */
46	const hasNoImportedValue = (
47	  value: SchemaFieldChange["importedValue"],
48	): boolean => value === undefined || value === "";
49	
50	const buildNodeTypeFieldChanges = ({
51	  local,
52	  imported,
53	}: {
54	  local: DiscourseNode;
55	  imported: DiscourseNode;
56	}): SchemaFieldChange[] => {
57	  return MERGEABLE_NODE_TYPE_FIELDS.flatMap((field) => {
58	    const localValue = local[field];
59	    const importedValue = imported[field];
60	    if (hasNoImportedValue(importedValue)) return [];
61	    if (localValue === importedValue) return [];
62	    return [{ field, localValue, importedValue }];
63	  });
64	};
65	
66	const buildRelationTypeFieldChanges = ({
67	  local,
68	  imported,
69	}: {
70	  local: DiscourseRelationType;
71	  imported: DiscourseRelationType;
72	}): SchemaFieldChange[] => {
73	  return MERGEABLE_RELATION_TYPE_FIELDS.flatMap((field) => {
74	    // Parsing coerces the imported color to a tldraw name; resolve the local one too, or an equivalent hex reads as a conflict and the value shown is not the one that would be stored.
75	    const localValue =
76	      field === "color" ? toTldrawColor(local.color) : local[field];
77	    const importedValue = imported[field];
78	    if (hasNoImportedValue(importedValue)) return [];
79	    if (localValue === importedValue) return [];
80	    return [{ field, localValue, importedValue }];
81	  });
82	};
83	
84	export const buildSchemaConflicts = ({
85	  schemaFile,
86	  matchPlan,
87	  localNodeTypes,
88	  localRelationTypes,
89	  localTemplateContents,
90	}: {
91	  schemaFile: DiscourseSchemaFile;
92	  matchPlan: SchemaImportMatchPlan;
93	  localNodeTypes: DiscourseNode[];
94	  localRelationTypes: DiscourseRelationType[];
95	  localTemplateContents: ReadonlyMap<string, string>;
96	}): SchemaConflict[] => {
97	  const localNodeTypesById = new Map(
98	    localNodeTypes.map((nodeType) => [nodeType.id, nodeType]),
99	  );
100	  const localRelationTypesById = new Map(
101	    localRelationTypes.map((relationType) => [relationType.id, relationType]),
102	  );
103	
104	  const nodeTypeConflicts = schemaFile.nodeTypes.flatMap((imported) => {
105	    if (!matchPlan.existingNodeTypeIds.has(imported.id)) return [];
106	    const localId = matchPlan.nodeTypeIdMapping.get(imported.id);
107	    const local = localId ? localNodeTypesById.get(localId) : undefined;
108	    if (!local) return [];
109	
110	    const changes = buildNodeTypeFieldChanges({ local, imported });
111	    if (changes.length === 0) return [];
112	    return [
113	      {
114	        category: "nodeType" as const,
115	        schemaId: imported.id,
116	        label: local.name,
117	        changes,
118	      },
119	    ];
120	  });
121	
122	  const relationTypeConflicts = schemaFile.relationTypes.flatMap((imported) => {
123	    if (!matchPlan.existingRelationTypeIds.has(imported.id)) return [];
124	    const localId = matchPlan.relationTypeIdMapping.get(imported.id);
125	    const local = localId ? localRelationTypesById.get(localId) : undefined;
126	    if (!local) return [];
127	
128	    const changes = buildRelationTypeFieldChanges({ local, imported });
129	    if (changes.length === 0) return [];
130	    return [
131	      {
132	        category: "relationType" as const,
133	        schemaId: imported.id,
134	        label: local.label,
135	        changes,
136	      },
137	    ];
138	  });
139	
140	  const templateConflicts = schemaFile.templates.flatMap((imported) => {
141	    if (!matchPlan.existingTemplateNames.has(imported.name)) return [];
142	    const localContent = localTemplateContents.get(imported.name);
143	    if (localContent === undefined || localContent === imported.content) {
144	      return [];
145	    }
146	    return [
147	      {
148	        category: "template" as const,
149	        schemaId: imported.name,
150	        label: `${imported.name}.md`,
151	        changes: [
152	          {
153	            field: TEMPLATE_CONTENT_FIELD,
154	            localValue: localContent,
155	            importedValue: imported.content,
156	          },
157	        ],
158	      },
159	    ];
160	  });
161	
162	  return [...nodeTypeConflicts, ...relationTypeConflicts, ...templateConflicts];
163	};
