76	export const useSchemaSelection = ({
77	  source,
78	  initialTemplateNames,
79	  resetKey,
80	}: {
81	  source: SchemaSelectionSource;
82	  /**
83	   * Template names to pre-select on mount and on reset. Defaults to all
84	   * templates in source when not provided.
85	   */
86	  initialTemplateNames?: string[];
87	  resetKey: string;
88	}): SchemaSelectionState => {
89	  const [selectedNodeTypeIds, setSelectedNodeTypeIds] = useState<Set<string>>(
90	    () => new Set(source.nodeTypes.map((nodeType) => nodeType.id)),
91	  );
92	  const [selectedRelationTypeIds, setSelectedRelationTypeIds] = useState<
93	    Set<string>
94	  >(() => new Set(source.relationTypes.map((relationType) => relationType.id)));
95	  const [selectedRelationIds, setSelectedRelationIds] = useState<Set<string>>(
96	    () => new Set(source.relationTriples.map((relation) => relation.id)),
97	  );
98	  const [selectedTemplateNames, setSelectedTemplateNames] = useState<
99	    Set<string>
100	  >(() => new Set(initialTemplateNames ?? source.templateNames));
101	
102	  // Reset during render when resetKey changes; source and
103	  // initialTemplateNames changing alone do not reset the selection.
104	  const [prevResetKey, setPrevResetKey] = useState(resetKey);
105	  if (resetKey !== prevResetKey) {
106	    setPrevResetKey(resetKey);
107	    setSelectedNodeTypeIds(
108	      new Set(source.nodeTypes.map((nodeType) => nodeType.id)),
109	    );
110	    setSelectedRelationTypeIds(
111	      new Set(source.relationTypes.map((relationType) => relationType.id)),
112	    );
113	    setSelectedRelationIds(
114	      new Set(source.relationTriples.map((relation) => relation.id)),
115	    );
116	    setSelectedTemplateNames(
117	      new Set(initialTemplateNames ?? source.templateNames),
118	    );
119	  }
120	
121	  const requiredRelationTypeIds = useMemo(() => {
122	    const requiredIds = new Set<string>();
123	    for (const relation of source.relationTriples) {
124	      if (selectedRelationIds.has(relation.id)) {
125	        requiredIds.add(relation.relationshipTypeId);
126	      }
127	    }
128	    return requiredIds;
129	  }, [source.relationTriples, selectedRelationIds]);
130	
131	  const requiredNodeTypeIds = useMemo(() => {
132	    const requiredIds = new Set<string>();
133	    for (const relation of source.relationTriples) {
134	      if (!selectedRelationIds.has(relation.id)) {
135	        continue;
136	      }
137	      requiredIds.add(relation.sourceId);
138	      requiredIds.add(relation.destinationId);
139	    }
140	    return requiredIds;
141	  }, [source.relationTriples, selectedRelationIds]);
142	
143	  useEffect(() => {
144	    setSelectedRelationTypeIds((previousSet) => {
145	      const nextSet = new Set(previousSet);
146	      let didChange = false;
147	      for (const relationTypeId of requiredRelationTypeIds) {
148	        if (!nextSet.has(relationTypeId)) {
149	          nextSet.add(relationTypeId);
150	          didChange = true;
151	        }
152	      }
153	      return didChange ? nextSet : previousSet;
154	    });
155	  }, [requiredRelationTypeIds]);
156	
157	  useEffect(() => {
158	    setSelectedNodeTypeIds((previousSet) => {
159	      const nextSet = new Set(previousSet);
160	      let didChange = false;
161	      for (const nodeTypeId of requiredNodeTypeIds) {
162	        if (!nextSet.has(nodeTypeId)) {
163	          nextSet.add(nodeTypeId);
164	          didChange = true;
165	        }
166	      }
167	      return didChange ? nextSet : previousSet;
168	    });
169	  }, [requiredNodeTypeIds]);
170	
171	  return {
172	    selectedNodeTypeIds,
173	    selectedRelationTypeIds,
174	    selectedRelationIds,
175	    selectedTemplateNames,
176	    requiredNodeTypeIds,
177	    requiredRelationTypeIds,
178	    selectAllNodeTypes: () =>
179	      setSelectedNodeTypeIds(
180	        new Set(source.nodeTypes.map((nodeType) => nodeType.id)),
181	      ),
182	    deselectOptionalNodeTypes: () =>
183	      setSelectedNodeTypeIds(new Set([...requiredNodeTypeIds])),
184	    toggleNodeType: (nodeTypeId, shouldSelect) => {
185	      if (!shouldSelect && requiredNodeTypeIds.has(nodeTypeId)) {
186	        return {
187	          ok: false,
188	          reason:
189	            "This node type is required by a selected relation triple. Remove the triple first.",
190	        };
191	      }
192	      setSelectedNodeTypeIds((previousSet) =>
193	        updateSet(previousSet, nodeTypeId, shouldSelect),
194	      );
195	      return { ok: true };
196	    },
197	    selectAllRelationTypes: () =>
198	      setSelectedRelationTypeIds(
199	        new Set(source.relationTypes.map((relationType) => relationType.id)),
200	      ),
201	    deselectOptionalRelationTypes: () =>
202	      setSelectedRelationTypeIds(new Set([...requiredRelationTypeIds])),
203	    toggleRelationType: (relationTypeId, shouldSelect) => {
204	      if (!shouldSelect && requiredRelationTypeIds.has(relationTypeId)) {
205	        return {
206	          ok: false,
207	          reason:
208	            "This relation type is required by a selected relation triple. Remove the triple first.",
209	        };
210	      }
211	      setSelectedRelationTypeIds((previousSet) =>
212	        updateSet(previousSet, relationTypeId, shouldSelect),
213	      );
214	      return { ok: true };
215	    },
216	    selectAllRelationTriples: () =>
217	      setSelectedRelationIds(
218	        new Set(source.relationTriples.map((relation) => relation.id)),
219	      ),
220	    deselectAllRelationTriples: () => setSelectedRelationIds(new Set()),
221	    toggleRelationTriple: (relationId, shouldSelect) =>
222	      setSelectedRelationIds((previousSet) =>
223	        updateSet(previousSet, relationId, shouldSelect),
224	      ),
225	    selectAllTemplates: () =>
226	      setSelectedTemplateNames(new Set(source.templateNames)),
227	    deselectAllTemplates: () => setSelectedTemplateNames(new Set()),
228	    toggleTemplate: (templateName, shouldSelect) =>
229	      setSelectedTemplateNames((previousSet) =>
230	        updateSet(previousSet, templateName, shouldSelect),
231	      ),
232	    asSelectionPayload: () => ({
233	      nodeTypeIds: [...selectedNodeTypeIds],
234	      relationTypeIds: [...selectedRelationTypeIds],
235	      discourseRelationIds: [...selectedRelationIds],
236	      templateNames: [...selectedTemplateNames],
237	    }),
238	  };
239	};
