// Pace input for viewers: split long moves into steps, pause on press/release and after direct evaluates.
const paced = (client) => {
  const send = client.send;
  const evaluate = client.evaluate;
  let last = null;
  client.send = async (method, params = {}) => {
    if (method !== "Input.dispatchMouseEvent") return send(method, params);
    if (params.type === "mouseMoved" && last) {
      const steps = Math.min(30, Math.floor(Math.hypot(params.x - last.x, params.y - last.y) / 25));
      for (let k = 1; k < steps; k++) {
        await send(method, { ...params, x: last.x + ((params.x - last.x) * k) / steps, y: last.y + ((params.y - last.y) * k) / steps });
        await wait(16);
      }
    }
    const r = await send(method, params);
    last = { x: params.x, y: params.y };
    // Keep press-to-press under tldraw's ~450ms double-click window.
    const pause = { mouseMoved: 16, mousePressed: 60, mouseReleased: 150 }[params.type] ?? 0;
    await wait((params.clickCount ?? 1) > 1 ? 0 : pause);
    return r;
  };
  client.evaluate = async (expr) => {
    const r = await evaluate(expr);
    await wait(250);
    return r;
  };
  return () => {
    client.send = send;
    client.evaluate = evaluate;
  };
};

