// ENG-2274: schema types in one file that differ only by case must import as separate types.
import { writeFileSync, mkdirSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const SCHEMA_PATH = path.join(HERE, "dg-schema-eng-2274.json");
const NODE_A = "eng2274-node-a";
const NODE_B = "eng2274-node-b";
const REL_A = "eng2274-rel-a";
const REL_B = "eng2274-rel-b";
const LOCAL_NODE = "eng2274-local-node";
const NAMES = ["Milestone", "milestone", "MILESTONE"];
const LABELS = ["Precedes", "precedes"];

const now = 1795737600000;
const schemaFile = {
  version: 1,
  exportedAt: "2026-11-27T00:00:00.000Z",
  pluginVersion: "1.5.2",
  vaultName: "ENG-2274 source vault",
  vaultId: "eng2274sourcevault",
  nodeTypes: [
    { id: NODE_A, name: "Milestone", format: "MLS - {content}", color: "#3b82f6", created: now, modified: now },
    { id: NODE_B, name: "milestone", format: "mls - {content}", color: "#ef4444", created: now, modified: now },
  ],
  relationTypes: [
    { id: REL_A, label: "Precedes", complement: "Follows", color: "blue", created: now, modified: now },
    { id: REL_B, label: "precedes", complement: "follows", color: "red", created: now, modified: now },
  ],
  discourseRelations: [
    { id: "eng2274-triple", sourceId: NODE_B, destinationId: NODE_B, relationshipTypeId: REL_B, created: now, modified: now },
  ],
  templates: [],
};

const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const plugin = (vault, json) => `app.plugins.plugins[${json(vault.pluginId)}]`;

const snapshot = async ({ client, vault, json }) => {
  mkdirSync(HERE, { recursive: true });
  writeFileSync(SCHEMA_PATH, JSON.stringify(schemaFile, null, 2));
  const saved = await client.evaluate(`const s = ${plugin(vault, json)}.settings;
    return JSON.stringify({ nodeTypes: s.nodeTypes, relationTypes: s.relationTypes, discourseRelations: s.discourseRelations });`);
  const clash = await client.evaluate(`const s = ${plugin(vault, json)}.settings;
    return s.nodeTypes.filter((t) => ${json(NAMES)}.includes(t.name)).length
      + s.relationTypes.filter((t) => ${json(LABELS)}.includes(t.label)).length;`);
  if (clash > 0) throw new Error("vault already has a Milestone/Precedes type; pick other names");
  // The native open dialog cannot be driven over CDP, so it is answered with the prepared file.
  await client.evaluate(`const e = window.require("electron"); const d = e.dialog ?? e.remote.dialog;
    window.__eng2274Dialog = d; window.__eng2274Open = d.showOpenDialog;
    d.showOpenDialog = async () => ({ canceled: false, filePaths: [${json(SCHEMA_PATH)}] });
    document.querySelectorAll(".notice").forEach((n) => n.remove());
    return true;`);
  return { saved };
};

const restore = async ({ client, vault, json }, { saved }) => {
  await client.evaluate(`return (async () => {
    if (window.__eng2274Dialog) window.__eng2274Dialog.showOpenDialog = window.__eng2274Open;
    const p = ${plugin(vault, json)};
    Object.assign(p.settings, JSON.parse(${json(saved)}));
    await p.saveSettings();
    document.querySelectorAll(".notice").forEach((n) => n.remove());
    return true;
  })();`);
};

const clickAt = async ({ client }, finder, label) => {
  const rect = await client.evaluate(`const el = ${finder};
    if (!el) return null;
    el.scrollIntoView({ block: "center" });
    const r = el.getBoundingClientRect();
    return { x: r.x + r.width / 2, y: r.y + r.height / 2 };`);
  if (!rect) throw new Error(`not found: ${label}`);
  const base = { x: rect.x, y: rect.y, button: "left", clickCount: 1 };
  await client.send("Input.dispatchMouseEvent", { ...base, type: "mouseMoved", button: "none" });
  await client.send("Input.dispatchMouseEvent", { ...base, type: "mousePressed" });
  await client.send("Input.dispatchMouseEvent", { ...base, type: "mouseReleased" });
};

const button = (json, text) =>
  `Array.from(document.querySelectorAll(".modal button")).find((b) => b.textContent.trim() === ${json(text)})`;
const row = (json, text) =>
  `Array.from(document.querySelectorAll(".modal label")).find((l) => l.querySelector("span")?.textContent === ${json(text)})`;
const checkbox = (json, text) => `${row(json, text)}?.querySelector("input")`;

const openPreview = async (ctx) => {
  const { client, vault, json } = ctx;
  await client.evaluate(`return app.commands.executeCommandById(${json(`${vault.pluginId}:import-dg-schema`)});`);
  await client.waitFor(`!!${button(json, "Choose schema file")}`, { label: "import modal open" });
  await clickAt(ctx, button(json, "Choose schema file"), "Choose schema file");
  await client.waitFor(`!!${row(json, "milestone")}`, { label: "preview rendered" });
  await wait(1200);
  return client.evaluate(`const rows = Array.from(document.querySelectorAll(".modal label"));
    return {
      rows: rows.map((l) => l.textContent.trim()),
      summary: Array.from(document.querySelectorAll(".modal .text-muted")).map((d) => d.textContent.trim())
        .filter((t) => /^(Node|Relation) types:/.test(t)),
    };`);
};

const importAndRead = async (ctx) => {
  const { client, vault, json } = ctx;
  await wait(800);
  await clickAt(ctx, button(json, "Import selected"), "Import selected");
  await client.waitFor(`Array.from(document.querySelectorAll(".notice")).some((n) => n.textContent.includes("Import complete"))`,
    { label: "import complete notice" });
  await wait(1800);
  return client.evaluate(`const s = ${plugin(vault, json)}.settings;
    const ids = ${json([NODE_A, NODE_B, LOCAL_NODE])}; const rels = ${json([REL_A, REL_B])};
    return {
      nodeTypes: s.nodeTypes.filter((t) => ids.includes(t.id)).map((t) => t.name).sort(),
      relationTypes: s.relationTypes.filter((t) => rels.includes(t.id)).map((t) => t.label).sort(),
      triples: s.discourseRelations.filter((r) => rels.includes(r.relationshipTypeId))
        .map((r) => [r.sourceId, r.relationshipTypeId, r.destinationId].join(" > ")),
      notices: Array.from(document.querySelectorAll(".notice")).map((n) => n.textContent.trim()),
    };`);
};

const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const noWarning = (result) => !result.notices.some((n) => n.includes("Import warnings"));

